actions.script:
if (!ec.search.isAvailable()) { ec.message.addError(ec.l10n.localize("Search is not configured, not indexing documents")); return; }
// the store for each document type is made or rebuilt as needed, so verifyIndexes has nothing more to do
ec.search.indexDocuments(documentList);

const startTime = Date.now();
documentsIndexed = ec.search.rebuildFeed({dataFeedId: dataFeedId, dataDocumentId: dataDocumentId,
        fromUpdateStamp: fromUpdateStamp, thruUpdateStamp: thruUpdateStamp, batchSize: batchSize});
ec.message.addMessage(`Indexed ${documentsIndexed} documents for feed ${dataFeedId} in ${Date.now() - startTime}ms`);

recordsCreated = 0;
documentList = [];
for (const allChildFileFlat of (allChildFileFlatList || [])) {
    const getWpiResult = ec.service.sync().name("org.moqui.resource.WikiServices.get#WikiPageId")
            .parameters({wikiSpaceId: wikiSpaceId, pagePath: allChildFileFlat.path, createIfMissing: true}).call();
    if (getWpiResult == null) return;
    if (getWpiResult.createdRecord) recordsCreated = recordsCreated + 1;
    for (const document of ec.entity.getDataDocuments(dataDocumentId, {wikiPageId: getWpiResult.wikiPageId})) documentList.push(document);
}
ec.service.sync().name("org.moqui.search.SearchServices.index#DataDocuments").parameter("documentList", documentList).call();
ec.message.addMessage(`Found and indexed ${(allChildFileFlatList || []).length} pages in Wiki Space ${wikiSpaceId}, created DB records for ${recordsCreated}.`);

const fromOffset = pageNoLimit ? 0 : pageIndex * pageSize;
// the result window is limited to 10000, as Elastic's default max_result_window
const sizeLimit = pageNoLimit ? 10000 : pageSize;
documentList = [];
documentListCount = 0;
documentListPageIndex = pageIndex;
documentListPageSize = pageSize;
documentListPageMaxIndex = 0;
documentListPageRangeLow = 0;
documentListPageRangeHigh = 0;

if (!ec.search.isAvailable()) { ec.message.addMessage(ec.l10n.localize("Search is not configured, not running search"), "danger"); return; }
const target = documentType ? {documentType: documentType} : {indexName: indexName};
if (!ec.search.indexExists(target)) {
    ec.logger.warn(`Tried to search with indexName ${indexName} that does not exist, returning empty list`);
    return;
}

const hasHighlights = highlightFields != null && highlightFields.length > 0;
let result;
try {
    const clauses = [ec.search.parseQuery(queryString)];
    if (nestedQueryMap) {
        for (const nestedPath of Object.keys(nestedQueryMap)) {
            const nestedQuery = ec.search.elasticQuery(nestedQueryMap[nestedPath]);
            clauses.push(nestedPath && nestedPath !== "null" ? {child: {path: nestedPath, query: nestedQuery}} : nestedQuery);
        }
    }
    if (query) clauses.push(query);
    result = ec.search.search(Object.assign({}, target, {query: {bool: {all: clauses}}, filter: filter, sort: orderByFields,
            highlight: highlightFields, offset: fromOffset, limit: sizeLimit}));
} catch (err) {
    ec.message.addMessage(`Invalid search: ${queryString} (${err && err.message ? err.message : err})`, "danger");
    return;
}

for (const hit of result.hits) {
    const document = Object.assign({}, flattenDocument ? ec.search.flatten(hit.body) : hit.body);
    document._index = hit.index;
    document._id = hit.id;
    document._type = hit.documentId;
    if (hasHighlights) document.highlights = hit.highlights;
    documentList.push(document);
}

documentListCount = result.total;
documentListPageMaxIndex = documentListCount > 0 ? Math.trunc((documentListCount - 1) / documentListPageSize) : 0;
documentListPageRangeLow = documentListPageIndex * documentListPageSize + 1;
documentListPageRangeHigh = (documentListPageIndex * documentListPageSize) + documentListPageSize;
if (documentListPageRangeHigh > documentListCount) documentListPageRangeHigh = documentListCount;

if (!ec.search.isAvailable()) { ec.message.addError(`Search is not configured, not deleting document ${documentId}`); return; }
const types = dataDocumentId ? ec.search.documentTypes({documentType: dataDocumentId}) :
        (indexName ? ec.search.documentTypes({indexName: indexName}) : []);
for (const type of types) ec.search.deleteDocument(type, documentId);

deletedCount = 0;
if (daysToKeep == null && !queryString) { ec.message.addError(ec.l10n.localize("To delete documents must specify daysToKeep, queryString, or both")); return; }
if (!ec.search.isAvailable()) { ec.message.addMessage(ec.l10n.localize("Search is not configured, not deleting documents"), "danger"); return; }
if (ec.search.documentTypes({indexName: indexName}).length === 0) {
    ec.message.addMessage(`The ${ec.search.backendName()} search backend has no index ${indexName}`, "warning");
    return;
}

const clauses = [];
if (queryString) clauses.push(ec.search.parseQuery(queryString));
if (daysToKeep != null) {
    const thruMillis = Date.now() - daysToKeep * 24 * 60 * 60 * 1000;
    clauses.push({field: {name: timestampField, op: "range", lte: thruMillis}});
}
deletedCount = ec.search.deleteMatching({indexName: indexName, filter: {bool: {all: clauses}}});

const resultMsg = `Deleted ${deletedCount} documents from index ${indexName} with days to keep ${daysToKeep} and query ${queryString}`;
ec.logger.info(resultMsg);
ec.message.addMessage(resultMsg);

embedded = 0;
if (!ec.search.isAvailable() || !ec.search.capabilities().includes("semantic")) return;
if (!indexName && !documentType) { ec.message.addError(ec.l10n.localize("To embed documents specify indexName or documentType")); return; }
const target = documentType ? {documentType: documentType} : {indexName: indexName};
embedded = ec.search.embedPending(Object.assign({batch: batch}, target));
